-- Passage rg4-story-details-inference-p08
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('317a3fda-bbd4-5726-978f-03e70f95305e', 'rg4-story-details-inference-p08', (select id from public.skills where slug = 'read-g4-story-details-inference'), null,
        '3-5', $q$Just a Rock$q$, $q$Hana and her cousin Mateo were wading in Pine Creek when Hana saw a flat gray stone with lines across it. The lines curved like the edge of a fan. She lifted it out of the water and turned it over in the sun.

"It's just a rock," Mateo said. He skipped a pebble across the water.

Hana didn't think so. The lines were too neat and even. She remembered a picture in her science book of a shell that had turned to stone. She wrapped the stone in her bandana and carried it home in both hands.

On Saturday, her aunt drove them to the county nature center. A scientist named Dr. Mensah looked at the stone through a magnifying glass for a long time. Then she took a thick book from a shelf and opened it to a drawing.

"This is a fossil of a sea animal called a brachiopod," she said. "It lived here millions of years ago, when this land was under a shallow sea."

Mateo leaned closer. "Under the sea? Pine Creek?"

Dr. Mensah asked if the center could borrow the fossil for its display case. Hana thought about it. Then she said yes, as long as the card had her name on it.

The next month, Mateo brought three friends to see the fossil. He told them the whole story. He did not mention the part where he called it a rock.$q$, 'draft')
